import React from 'react';
import { Pressable, Text, View } from 'react-native';
import { ChevronLeft, Sparkles } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';

interface StudioHeaderProps {
  title: string;
  onBack: () => void;
  rightAction?: React.ReactNode;
}

export function StudioHeader({ title, onBack, rightAction }: StudioHeaderProps) {
  return (
    <View className="px-5 py-3">
      <View className="flex-row items-center justify-between">
        <Pressable
          onPress={onBack}
          accessibilityRole="button"
          accessibilityLabel="Go back"
          className="h-10 w-10 rounded-xl bg-white border border-gray-100 items-center justify-center"
          style={{
            shadowColor: '#7C3AED',
            shadowOffset: { width: 0, height: 2 },
            shadowOpacity: 0.08,
            shadowRadius: 6,
            elevation: 2,
          }}>
          <ChevronLeft size={20} color="#7C3AED" />
        </Pressable>
        <View className="flex-1 items-center mx-2">
          <View className="flex-row items-center gap-1 mb-0.5">
            <Sparkles size={12} color="#7C3AED" />
            <Text className="text-[10px] font-bold text-primary uppercase tracking-wide">
              Surprise Link Studio
            </Text>
          </View>
          <Text className="text-[15px] font-bold text-foreground text-center" numberOfLines={1}>
            {title}
          </Text>
        </View>
        <View className="min-w-[40px] items-end">{rightAction}</View>
      </View>
    </View>
  );
}

interface ContinueButtonProps {
  label?: string;
  onPress: () => void;
  disabled?: boolean;
}

export function ContinueButton({ label = 'Continue', onPress, disabled }: ContinueButtonProps) {
  return (
    <View className="px-5 pb-5 pt-2 border-t border-border/30 bg-background">
      <Pressable
        onPress={onPress}
        disabled={disabled}
        accessibilityRole="button"
        accessibilityLabel={label}
        className={`rounded-2xl overflow-hidden ${disabled ? 'opacity-50' : ''}`}
        style={({ pressed }) => ({
          transform: [{ scale: pressed && !disabled ? 0.98 : 1 }],
        })}>
        <LinearGradient
          colors={disabled ? ['#9CA3AF', '#6B7280'] : ['#7C3AED', '#EC4899']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 0 }}
          className="py-4 items-center">
          <Text className="text-white text-[15px] font-bold">{label}</Text>
        </LinearGradient>
      </Pressable>
    </View>
  );
}
