import React from 'react';
import { Pressable, Text, View } from 'react-native';
import { ChevronLeft, Sparkles, Star } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { useAIWishesStore } from '../store/ai-wishes.store';

type Props = {
  onBack: () => void;
};

export function WishHeader({ onBack }: Props) {
  const credits = useAIWishesStore((s) => s.credits);

  return (
    <LinearGradient
      colors={['#7C3AED', '#6D28D9', '#5B21B6']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      className="px-5 pt-2 pb-5">
      <Animated.View
        entering={FadeInDown.duration(400)}
        className="flex-row items-center justify-between">
        <Pressable
          onPress={onBack}
          className="h-10 w-10 rounded-full bg-white/15 items-center justify-center active:bg-white/25"
          accessibilityRole="button"
          accessibilityLabel="Go back">
          <ChevronLeft size={20} color="#FFFFFF" />
        </Pressable>

        <View className="flex-1 items-center px-2">
          <View className="flex-row items-center gap-2">
            <Sparkles size={20} color="#FCD34D" />
            <Text className="text-[20px] font-black text-white tracking-tight">
              AI Wish Generator
            </Text>
          </View>
          <Text className="text-[12px] text-white/70 mt-0.5 text-center">
            Craft personalized birthday messages
          </Text>
        </View>

        <View className="rounded-full bg-white/15 border border-white/25 px-3 py-1.5 flex-row items-center gap-1.5">
          <Star size={12} color="#FCD34D" fill="#FCD34D" />
          <Text className="text-[13px] font-bold text-white">{credits}</Text>
        </View>
      </Animated.View>
    </LinearGradient>
  );
}
