import React from 'react';
import { Pressable, ScrollView, Text, View } from 'react-native';
import {
  Camera,
  ImagePlus,
  Layers,
  Palette,
  Shapes,
  Sparkles,
  Type,
  Wand2,
} from 'lucide-react-native';

import { useCardStudioStore } from '../../store/card-studio.store';
import { useCardEditor } from '../../hooks/useCardEditor';
import { BackgroundStudio } from './BackgroundStudio';
import { DecorationPicker } from './DecorationPicker';
import { ElementActionBar } from './ElementActionBar';
import { FormatPicker } from './FormatPicker';
import { ImageControls } from './ImageControls';
import { PersonalizationForm } from './PersonalizationForm';
import { QuickDesignPanel } from './QuickDesignPanel';
import { TextControls } from './TextControls';
import { feedback } from '@/shared/feedback';
import * as ImagePicker from 'expo-image-picker';

const TOOL_ITEMS = [
  { id: 'quick' as const, label: 'Quick', icon: Wand2 },
  { id: 'background' as const, label: 'Background', icon: Palette },
  { id: 'elements' as const, label: 'Stickers', icon: Shapes },
  { id: 'content' as const, label: 'Content', icon: Type },
  { id: 'image' as const, label: 'Photo', icon: ImagePlus },
];

export function ContextualToolbar() {
  const activePanel = useCardStudioStore((s) => s.activePanel);
  const setActivePanel = useCardStudioStore((s) => s.setActivePanel);
  const editorModeValue = useCardStudioStore((s) => s.editorMode);
  const setEditorMode = useCardStudioStore((s) => s.setEditorMode);
  const selectedElement = useCardStudioStore((s) =>
    s.selectedElementId ? s.elements.find((e) => e.id === s.selectedElementId) ?? null : null,
  );
  const selectElement = useCardStudioStore((s) => s.selectElement);
  const isDragging = useCardStudioStore((s) => s.isDragging);
  const { addTextElement, addShapeElement } = useCardEditor();
  const addElement = useCardStudioStore((s) => s.addElement);

  const addPhotoElement = async () => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== 'granted') {
      feedback.error('Permission needed', 'Allow photo library to add image elements.');
      return;
    }

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      quality: 0.85,
    });

    if (result.canceled || !result.assets[0]) return;

    const maxZ = Math.max(
      0,
      ...useCardStudioStore.getState().elements.map((element) => element.zIndex),
    );
    addElement({
      id: `el-${Date.now()}`,
      type: 'image',
      uri: result.assets[0].uri,
      x: 52,
      y: 95,
      width: 180,
      height: 180,
      rotation: 0,
      opacity: 1,
      zIndex: maxZ + 1,
      visible: true,
      borderRadius: 18,
    });
  };

  const renderPanel = () => {
    if (selectedElement?.type === 'text') {
      return (
        <>
          <ElementActionBar element={selectedElement} />
          <TextControls element={selectedElement} />
        </>
      );
    }
    if (selectedElement?.type === 'image') {
      return (
        <>
          <ElementActionBar element={selectedElement} />
          <ImageControls element={selectedElement} />
        </>
      );
    }
    if (selectedElement) {
      return <ElementActionBar element={selectedElement} />;
    }

    switch (activePanel) {
      case 'quick':
        return <QuickDesignPanel />;
      case 'background':
        return (
          <>
            <FormatPicker />
            <BackgroundStudio />
          </>
        );
      case 'elements':
        return (
          <View>
            <View style={{ marginHorizontal: 16, marginBottom: 12, flexDirection: 'row', gap: 8 }}>
              <Pressable
                onPress={() => addTextElement('Your text here')}
                style={{
                  flex: 1,
                  paddingVertical: 12,
                  borderRadius: 16,
                  backgroundColor: 'rgba(124,58,237,0.1)',
                  borderWidth: 1,
                  borderColor: 'rgba(124,58,237,0.2)',
                  alignItems: 'center',
                }}
                accessibilityRole="button">
                <Text style={{ fontSize: 13, fontWeight: '700', color: '#7C3AED' }}>+ Add Text</Text>
              </Pressable>
              <Pressable
                onPress={addPhotoElement}
                style={{
                  flex: 1,
                  paddingVertical: 12,
                  borderRadius: 16,
                  backgroundColor: 'rgba(236,72,153,0.1)',
                  borderWidth: 1,
                  borderColor: 'rgba(236,72,153,0.2)',
                  alignItems: 'center',
                  flexDirection: 'row',
                  justifyContent: 'center',
                  gap: 6,
                }}
                accessibilityRole="button">
                <ImagePlus size={14} color="#EC4899" />
                <Text style={{ fontSize: 13, fontWeight: '700', color: '#EC4899' }}>+ Add Photo</Text>
              </Pressable>
            </View>
            <View style={{ marginHorizontal: 16, marginBottom: 12, flexDirection: 'row', gap: 8 }}>
              <Pressable
                onPress={() => addShapeElement('rounded')}
                style={{
                  flex: 1,
                  paddingVertical: 10,
                  borderRadius: 12,
                  backgroundColor: '#F9FAFB',
                  borderWidth: 1,
                  borderColor: '#E5E7EB',
                  alignItems: 'center',
                }}
                accessibilityRole="button">
                <Text style={{ fontSize: 12, fontWeight: '600', color: '#6B7280' }}>Add Shape</Text>
              </Pressable>
              <Pressable
                onPress={async () => {
                  const cameraPerm = await ImagePicker.requestCameraPermissionsAsync();
                  if (cameraPerm.status !== 'granted') {
                    feedback.error('Permission needed', 'Allow camera access first.');
                    return;
                  }
                  const result = await ImagePicker.launchCameraAsync({
                    allowsEditing: true,
                    quality: 0.85,
                    mediaTypes: ['images'],
                  });
                  if (result.canceled || !result.assets[0]) return;
                  const maxZ = Math.max(
                    0,
                    ...useCardStudioStore.getState().elements.map((element) => element.zIndex),
                  );
                  addElement({
                    id: `el-${Date.now()}`,
                    type: 'image',
                    uri: result.assets[0].uri,
                    x: 52,
                    y: 95,
                    width: 180,
                    height: 180,
                    rotation: 0,
                    opacity: 1,
                    zIndex: maxZ + 1,
                    visible: true,
                    borderRadius: 18,
                  });
                }}
                style={{
                  flex: 1,
                  paddingVertical: 10,
                  borderRadius: 12,
                  backgroundColor: '#F9FAFB',
                  borderWidth: 1,
                  borderColor: '#E5E7EB',
                  alignItems: 'center',
                  flexDirection: 'row',
                  justifyContent: 'center',
                  gap: 6,
                }}
                accessibilityRole="button">
                <Camera size={14} color="#6B7280" />
                <Text style={{ fontSize: 12, fontWeight: '600', color: '#6B7280' }}>Camera Shot</Text>
              </Pressable>
            </View>
            <DecorationPicker />
          </View>
        );
      case 'content':
        return (
          <ScrollView style={{ maxHeight: 256 }} showsVerticalScrollIndicator={false} scrollEnabled={!isDragging}>
            <PersonalizationForm />
          </ScrollView>
        );
      case 'image':
        return (
          <View style={{ paddingHorizontal: 16, paddingVertical: 12 }}>
            <Text style={{ fontSize: 12, color: '#9CA3AF', textAlign: 'center' }}>
              Tap a photo on the canvas to edit, or add one from Quick Design mode.
            </Text>
          </View>
        );
      default:
        return (
          <View style={{ paddingHorizontal: 16, paddingVertical: 16, alignItems: 'center' }}>
            <Sparkles size={20} color="#7C3AED" />
            <Text style={{ fontSize: 13, fontWeight: '600', color: '#111827', marginTop: 8 }}>
              Tap a tool to start editing
            </Text>
            <Text style={{ fontSize: 11, color: '#9CA3AF', marginTop: 4, textAlign: 'center' }}>
              Select an element on canvas for contextual controls
            </Text>
          </View>
        );
    }
  };

  const isQuickMode = editorModeValue === 'quick';

  return (
    <View style={{ flex: 1, borderTopWidth: 1, borderTopColor: '#F3F4F6', backgroundColor: '#FFFFFF' }}>
      {/* Mode switcher */}
      <View style={{ flexDirection: 'row', marginHorizontal: 16, marginTop: 8, marginBottom: 4, padding: 4, backgroundColor: '#F3F4F6', borderRadius: 12 }}>
        <Pressable
          onPress={() => {
            selectElement(null);
            setEditorMode('quick');
          }}
          style={{
            flex: 1,
            paddingVertical: 8,
            borderRadius: 8,
            alignItems: 'center',
            backgroundColor: isQuickMode ? '#FFFFFF' : 'transparent',
            ...(isQuickMode ? { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.08, shadowRadius: 2, elevation: 1 } : {}),
          }}
          accessibilityRole="button"
          accessibilityState={{ selected: isQuickMode }}>
          <Text style={{ fontSize: 11, fontWeight: '700', color: isQuickMode ? '#7C3AED' : '#9CA3AF' }}>
            Quick Mode
          </Text>
        </Pressable>
        <Pressable
          onPress={() => {
            selectElement(null);
            setEditorMode('advanced');
          }}
          style={{
            flex: 1,
            paddingVertical: 8,
            borderRadius: 8,
            alignItems: 'center',
            backgroundColor: !isQuickMode ? '#FFFFFF' : 'transparent',
            ...(!isQuickMode ? { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.08, shadowRadius: 2, elevation: 1 } : {}),
          }}
          accessibilityRole="button"
          accessibilityState={{ selected: !isQuickMode }}>
          <Text style={{ fontSize: 11, fontWeight: '700', color: !isQuickMode ? '#7C3AED' : '#9CA3AF' }}>
            Advanced
          </Text>
        </Pressable>
      </View>

      <View style={{ paddingHorizontal: 16, paddingBottom: 4 }}>
        <Text style={{ fontSize: 10, color: '#9CA3AF', fontWeight: '600' }}>
          {isQuickMode ? 'Quick mode' : 'Advanced mode'} active
        </Text>
      </View>

      {/* Tool tabs - only when no element is selected */}
      {!selectedElement ? (
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ borderBottomWidth: 1, borderBottomColor: '#FAFAFA', flexGrow: 0 }}
          contentContainerStyle={{ paddingHorizontal: 12, paddingVertical: 8, gap: 4 }}>
          {TOOL_ITEMS.map(({ id, label, icon: Icon }) => {
            const isActive = activePanel === id;
            return (
              <Pressable
                key={id}
                onPress={() => setActivePanel(isActive ? 'none' : id)}
                style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  gap: 6,
                  paddingHorizontal: 14,
                  paddingVertical: 10,
                  borderRadius: 12,
                  backgroundColor: isActive ? 'rgba(124,58,237,0.1)' : 'transparent',
                }}
                accessibilityRole="button"
                accessibilityState={{ selected: isActive }}>
                <Icon size={14} color={isActive ? '#7C3AED' : '#9CA3AF'} />
                <Text style={{ fontSize: 12, fontWeight: '600', color: isActive ? '#7C3AED' : '#9CA3AF' }}>
                  {label}
                </Text>
              </Pressable>
            );
          })}
          <Pressable
            onPress={() => setActivePanel(activePanel === 'background' ? 'none' : 'background')}
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              gap: 6,
              paddingHorizontal: 14,
              paddingVertical: 10,
              borderRadius: 12,
              backgroundColor: activePanel === 'background' ? 'rgba(124,58,237,0.1)' : 'transparent',
            }}
            accessibilityRole="button">
            <Layers size={14} color={activePanel === 'background' ? '#7C3AED' : '#9CA3AF'} />
            <Text style={{ fontSize: 12, fontWeight: '600', color: activePanel === 'background' ? '#7C3AED' : '#9CA3AF' }}>
              Format
            </Text>
          </Pressable>
        </ScrollView>
      ) : (
        <View style={{ paddingHorizontal: 16, paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: '#FAFAFA' }}>
          <Text style={{ fontSize: 11, fontWeight: '600', color: '#7C3AED', textTransform: 'capitalize' }}>
            Editing {selectedElement.type}
          </Text>
        </View>
      )}

      {/* Panel content */}
      <ScrollView
        style={{ flex: 1 }}
        scrollEnabled={!isDragging}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        nestedScrollEnabled>
        {renderPanel()}
      </ScrollView>
    </View>
  );
}
